        using LCK10 = Field<_LCKR, 10, 1>; // Port x lock bit y (y= 0..15) These bits are read/write but can only be written when the LCKK bit is 0.
        using LCK11 = Field<_LCKR, 11, 1>; // Port x lock bit y (y= 0..15) These bits are read/write but can only be written when the LCKK bit is 0.
        using LCK12 = Field<_LCKR, 12, 1>; // Port x lock bit y (y= 0..15) These bits are read/write but can only be written when the LCKK bit is 0.
