// --------------------------------------------
// ADC3_Common: Analog-to-Digital Converter
// Base address: 0x58026300
// --------------------------------------------
template <uint32_t BASE_ADDR>
struct ADC3_Common_T {
    static constexpr uint32_t ADC3_Common_T_BASE = BASE_ADDR;

    // ADC Common status register
    struct _CSR : Register<ADC3_Common_T_BASE + 0x0, ReadOnly, _CSR> {
        using ADRDY_MST = Field<_CSR, 0, 1>; // Master ADC ready
        using EOSMP_MST = Field<_CSR, 1, 1>; // End of Sampling phase flag of the master ADC
        using EOC_MST = Field<_CSR, 2, 1>; // End of regular conversion of the master ADC
        using EOS_MST = Field<_CSR, 3, 1>; // End of regular sequence flag of the master ADC
        using OVR_MST = Field<_CSR, 4, 1>; // Overrun flag of the master ADC
        using JEOC_MST = Field<_CSR, 5, 1>; // End of injected conversion flag of the master ADC
        using JEOS_MST = Field<_CSR, 6, 1>; // End of injected sequence flag of the master ADC
        using AWD1_MST = Field<_CSR, 7, 1>; // Analog watchdog 1 flag of the master ADC
        using AWD2_MST = Field<_CSR, 8, 1>; // Analog watchdog 2 flag of the master ADC
        using AWD3_MST = Field<_CSR, 9, 1>; // Analog watchdog 3 flag of the master ADC
        using JQOVF_MST = Field<_CSR, 10, 1>; // Injected Context Queue Overflow flag of the master ADC
        using ADRDY_SLV = Field<_CSR, 16, 1>; // Slave ADC ready
        using EOSMP_SLV = Field<_CSR, 17, 1>; // End of Sampling phase flag of the slave ADC
        using EOC_SLV = Field<_CSR, 18, 1>; // End of regular conversion of the slave ADC
        using EOS_SLV = Field<_CSR, 19, 1>; // End of regular sequence flag of the slave ADC
        using OVR_SLV = Field<_CSR, 20, 1>; // Overrun flag of the slave ADC
        using JEOC_SLV = Field<_CSR, 21, 1>; // End of injected conversion flag of the slave ADC
        using JEOS_SLV = Field<_CSR, 22, 1>; // End of injected sequence flag of the slave ADC
        using AWD1_SLV = Field<_CSR, 23, 1>; // Analog watchdog 1 flag of the slave ADC
        using AWD2_SLV = Field<_CSR, 24, 1>; // Analog watchdog 2 flag of the slave ADC
        using AWD3_SLV = Field<_CSR, 25, 1>; // Analog watchdog 3 flag of the slave ADC
        using JQOVF_SLV = Field<_CSR, 26, 1>; // Injected Context Queue Overflow flag of the slave ADC
    };

    // ADC common control register
    struct _CCR : Register<ADC3_Common_T_BASE + 0x8, ReadWrite, _CCR> {
        using DUAL = Field<_CCR, 0, 5>; // Dual ADC mode selection
        using DELAY = Field<_CCR, 8, 4>; // Delay between 2 sampling phases
        using DAMDF = Field<_CCR, 14, 2>; // Dual ADC Mode Data Format
        using CKMODE = Field<_CCR, 16, 2>; // ADC clock mode
        using PRESC = Field<_CCR, 18, 4>; // ADC prescaler
        using VREFEN = Field<_CCR, 22, 1>; // VREFINT enable
        using VSENSEEN = Field<_CCR, 23, 1>; // Temperature sensor enable
        using VBATEN = Field<_CCR, 24, 1>; // VBAT enable
    };

    // ADC common regular data register for dual and triple modes
    struct _CDR : Register<ADC3_Common_T_BASE + 0xC, ReadOnly, _CDR> {
        using RDATA_SLV = Field<_CDR, 16, 16>; // Regular data of the slave ADC
        using RDATA_MST = Field<_CDR, 0, 16>; // Regular data of the master ADC
    };

    // ADC x common regular data register for 32-bit dual mode
    struct _CDR2 : Register<ADC3_Common_T_BASE + 0x10, ReadOnly, _CDR2> {
        using RDATA_ALT = Field<_CDR2, 0, 32>; // Regular data of the master/slave alternated ADCs
    };

}; // struct ADC3_Common_T

using ADC3_Common = ADC3_Common_T<0x58026300>;
