        using CHTIF3 = Field<_LIFCR, 26, 1>; // Stream x clear half transfer interrupt flag (x = 3..0)
        using CTEIF3 = Field<_LIFCR, 25, 1>; // Stream x clear transfer error interrupt flag (x = 3..0)
