        using RXFF = Field<_ISR, 24, 1>; // RXFIFO Full
        using TXFE = Field<_ISR, 23, 1>; // TXFIFO Empty
        using REACK = Field<_ISR, 22, 1>; // REACK
        using TEACK = Field<_ISR, 21, 1>; // TEACK
