// --------------------------------------------
// CAN_CCU: CCU registers
// Base address: 0x4000A800
// --------------------------------------------
struct CAN_CCU {
    static constexpr uint32_t CAN_CCU_BASE = 0x4000A800;

    // Clock Calibration Unit Core Release Register
    struct _CREL : Register<CAN_CCU_BASE + 0x0, ReadWrite, _CREL> {
        using DAY = Field<_CREL, 0, 8>; // Time Stamp Day
        using MON = Field<_CREL, 8, 8>; // Time Stamp Month
        using YEAR = Field<_CREL, 16, 4>; // Time Stamp Year
        using SUBSTEP = Field<_CREL, 20, 4>; // Sub-step of Core Release
        using STEP = Field<_CREL, 24, 4>; // Step of Core Release
        using REL = Field<_CREL, 28, 4>; // Core Release
    };

    // Calibration Configuration Register
    struct _CCFG : Register<CAN_CCU_BASE + 0x4, ReadWrite, _CCFG> {
        using TQBT = Field<_CCFG, 0, 5>; // Time Quanta per Bit Time
        using BCC = Field<_CCFG, 6, 1>; // Bypass Clock Calibration
        using CFL = Field<_CCFG, 7, 1>; // Calibration Field Length
        using OCPM = Field<_CCFG, 8, 8>; // Oscillator Clock Periods Minimum
        using CDIV = Field<_CCFG, 16, 4>; // Clock Divider
        using SWR = Field<_CCFG, 31, 1>; // Software Reset
    };

    // Calibration Status Register
    struct _CSTAT : Register<CAN_CCU_BASE + 0x8, ReadWrite, _CSTAT> {
        using OCPC = Field<_CSTAT, 0, 18>; // Oscillator Clock Period Counter
        using TQC = Field<_CSTAT, 18, 11>; // Time Quanta Counter
        using CALS = Field<_CSTAT, 30, 2>; // Calibration State
    };

    // Calibration Watchdog Register
    struct _CWD : Register<CAN_CCU_BASE + 0xC, ReadWrite, _CWD> {
        using WDC = Field<_CWD, 0, 16>; // WDC
        using WDV = Field<_CWD, 16, 16>; // WDV
    };

    // Clock Calibration Unit Interrupt Register
    struct _IR : Register<CAN_CCU_BASE + 0x10, ReadWrite, _IR> {
        using CWE = Field<_IR, 0, 1>; // Calibration Watchdog Event
        using CSC = Field<_IR, 1, 1>; // Calibration State Changed
    };

    // Clock Calibration Unit Interrupt Enable Register
    struct _IE : Register<CAN_CCU_BASE + 0x14, ReadWrite, _IE> {
        using CWEE = Field<_IE, 0, 1>; // Calibration Watchdog Event Enable
        using CSCE = Field<_IE, 1, 1>; // Calibration State Changed Enable
    };

}; // struct CAN_CCU

