        using DBG_TIM6 = Field<_APB1LFZ1, 4, 1>; // TIM6 stop in debug
        using DBG_TIM7 = Field<_APB1LFZ1, 5, 1>; // TIM7 stop in debug
        using DBG_TIM12 = Field<_APB1LFZ1, 6, 1>; // TIM12 stop in debug
        using DBG_TIM13 = Field<_APB1LFZ1, 7, 1>; // TIM13 stop in debug
